import{_ as t,o as s,c as a,ao as i}from"./chunks/framework.BLTYBhiq.js";const k=JSON.parse('{"title":"Parallel and distributed builds","description":"","frontmatter":{},"headers":[],"relativePath":"guide/parallel.md","filePath":"guide/parallel.md","lastUpdated":null}'),r={name:"guide/parallel.md"};function o(n,e,h,l,d,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="Parallel-and-distributed-builds" tabindex="-1">Parallel and distributed builds <a class="header-anchor" href="#Parallel-and-distributed-builds" aria-label="Permalink to &quot;Parallel and distributed builds {#Parallel-and-distributed-builds}&quot;">​</a></h1><p>By default <a href="/stable/api#Targets.tar_make"><code>tar_make</code></a> builds one target at a time, in your session. Two options let it do more at once:</p><ul><li><p><code>jobs = n</code> runs up to <code>n</code> targets and branches at the same time as Julia tasks in your session.</p></li><li><p><code>executor = DistributedExecutor(pids)</code> runs them on other Julia processes, the <em>workers</em>, which can be on other machines.</p></li></ul><p>Both work with any pipeline: switching between them does not change any target, any result or what counts as outdated. Every target runs with its own <a href="/stable/guide/builds#Random-seeds">seed</a>, so results also do not depend on how many targets ran at once or where.</p><h2 id="Jobs,-tasks,-threads,-slots-and-workers" tabindex="-1">Jobs, tasks, threads, slots and workers <a class="header-anchor" href="#Jobs,-tasks,-threads,-slots-and-workers" aria-label="Permalink to &quot;Jobs, tasks, threads, slots and workers {#Jobs,-tasks,-threads,-slots-and-workers}&quot;">​</a></h2><p>These words mean different things, and the settings below each control one of them:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Term</th><th style="text-align:right;">What it is</th><th style="text-align:right;">Set with</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>job</strong></td><td style="text-align:right;">One piece of work for the build: one target, or one branch of a branching target</td><td style="text-align:right;">the pipeline</td></tr><tr><td style="text-align:right;"><strong>task</strong></td><td style="text-align:right;">Julia&#39;s unit of concurrent work, sometimes called a <em>green thread</em>: cheap to create, run by Julia on one of its threads, and able to pause (for I/O, <code>sleep</code>, a lock or an external program) so another task runs on the same thread</td><td style="text-align:right;"><code>Threads.@spawn</code>; Targets makes one per job</td></tr><tr><td style="text-align:right;"><strong>thread</strong></td><td style="text-align:right;">An operating-system thread that runs tasks, one at a time. Julia&#39;s <em>default threadpool</em> has a fixed number of them, chosen at startup</td><td style="text-align:right;"><code>julia -t 8</code> or <code>JULIA_NUM_THREADS</code></td></tr><tr><td style="text-align:right;"><strong>slot</strong></td><td style="text-align:right;">One unit of a build&#39;s capacity, used only to decide what may start</td><td style="text-align:right;"><code>jobs = n</code> (<code>n</code> slots); <code>slots</code> per target</td></tr><tr><td style="text-align:right;"><strong>worker</strong></td><td style="text-align:right;">A separate Julia process, with its own memory, threads, loaded packages and global variables, on this machine or another</td><td style="text-align:right;"><code>addprocs</code>, ClusterManagers.jl, SlurmClusterManager.jl; <a href="/stable/api#Targets.DistributedExecutor"><code>DistributedExecutor</code></a></td></tr></tbody></table><p>They relate like this:</p><ul><li><p><strong>A build has a number of slots.</strong> With <code>jobs = n</code> it has <code>n</code>. With a <code>DistributedExecutor</code>, it has one per worker, or <code>slots_per_worker</code> per worker. When <code>executor</code> is given, <code>jobs</code> is ignored.</p></li><li><p><strong>Each job occupies slots while it runs</strong>: one by default, or the target&#39;s <code>slots</code>. A job starts only when its slots are free (or nothing else is running).</p></li><li><p><strong>Each running job is a task.</strong> With <code>jobs = n</code>, the task runs in your session and Julia puts it on any free thread of the default threadpool. With workers, the job is sent to a worker and runs there as a task.</p></li><li><p><strong>Threads are what run tasks in parallel.</strong> Slots and tasks only decide what is <em>started</em>; how many tasks make progress at the same instant is limited by the number of threads (for workers, see <a href="/stable/guide/parallel#Threads-on-workers">Threads on workers</a>).</p></li></ul><p>The build itself (deciding what is outdated, starting jobs, and recording their results) runs in the task that called <code>tar_make</code>. Jobs only compute their value and write it to the store; everything else waits for them to report back. When the build has a single slot (<code>jobs = 1</code>, the default), jobs run directly in that task, one after another, and no tasks are created.</p><h2 id="Jobs-and-threads" tabindex="-1">Jobs and threads <a class="header-anchor" href="#Jobs-and-threads" aria-label="Permalink to &quot;Jobs and threads {#Jobs-and-threads}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tar_make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(jobs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tar_make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(jobs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># one job per thread of the default threadpool</span></span></code></pre></div><p><code>jobs</code> counts tasks, not threads. A task keeps its thread until it pauses, so:</p><ul><li><p><strong>More jobs than threads</strong> still helps targets that mostly wait: downloads, reading and writing files, external programs, Quarto renders. While one waits, another runs. CPU-bound targets only take turns, so they finish no sooner than one at a time. <code>jobs = 4</code> in a session started without <code>-t</code> behaves like this.</p></li><li><p><strong>No more jobs than threads</strong> lets CPU-bound targets run in parallel. Threads not used by jobs are available to tasks that targets start themselves.</p></li><li><p><code>jobs = :auto</code> is <code>Threads.nthreads(:default)</code>: the number of default threads, so <code>1</code> when Julia was started without <code>-t</code>.</p></li></ul><p>To run CPU-bound targets in parallel, start Julia with threads, e.g. <code>julia -t 8</code>, and use <code>jobs = 8</code> or <code>jobs = :auto</code>. A project can make this the default in its <code>LocalPreferences.toml</code>, which <code>tar_make</code> reads only when <code>jobs</code> and <code>executor</code> are not given:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Targets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">jobs = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or a number such as 4</span></span></code></pre></div><p>When several jobs are ready, those on the longest remaining path through the pipeline (by the targets&#39; last build times) start first, so that the build as a whole finishes sooner. With one slot, targets are built in the pipeline&#39;s order.</p><p>Jobs run on any thread, and may move between threads while they run, so target code must not rely on <code>Threads.threadid()</code>.</p><p>The progress footer is redrawn from Julia&#39;s interactive threadpool when there is one (as with <code>julia -t 8,1</code>), so it keeps updating even when CPU-bound targets occupy every default thread.</p><h2 id="Slots" tabindex="-1">Slots <a class="header-anchor" href="#Slots" aria-label="Permalink to &quot;Slots {#Slots}&quot;">​</a></h2><p>A target&#39;s <code>slots</code> option (default <code>1</code>) is how many of the build&#39;s slots it occupies while it runs. Use it for targets that are parallel themselves, so that the build leaves room for them:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> posterior </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sample_chains</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model, data)  slots </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> simulation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> run_simulation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(settings)   slots </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :all</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # runs with nothing else</span></span></code></pre></div><ul><li><p>A number larger than the build&#39;s slots counts as all of them; <code>:all</code> is all of them.</p></li><li><p>Jobs start strictly in priority order: when the next job&#39;s slots are not free, the build waits for running jobs to finish instead of starting smaller jobs behind it. So a <code>slots = :all</code> target waits for everything running to finish, and nothing starts until it is done.</p></li><li><p><a href="/stable/api#Targets.tar_slots"><code>tar_slots</code></a><code>()</code> returns the slots the running target was given, to size its own parallelism:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sample_chains</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model, data) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    OhMyThreads</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tmap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(k </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sample_chain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model, data, k), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; ntasks </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> tar_slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div></li></ul><p><strong>Slots do not limit what a target uses.</strong> They only decide what else the build starts next to it. Julia cannot confine a task to some of its threads, so a <code>slots = 1</code> target that starts 16 tasks of its own can still use every thread. A target&#39;s own tasks share the default threadpool with the build&#39;s jobs; the two levels never deadlock, but together they can keep more tasks busy than there are slots.</p><h3 id="BLAS-threads" tabindex="-1">BLAS threads <a class="header-anchor" href="#BLAS-threads" aria-label="Permalink to &quot;BLAS threads {#BLAS-threads}&quot;">​</a></h3><p>Linear algebra libraries (OpenBLAS, MKL) use their own threads, which are neither Julia threads nor slots. When several BLAS-heavy targets run at once, each can try to use every core, and they slow each other down. Set <code>BLAS.set_num_threads(1)</code> (from <code>LinearAlgebra</code>) in the session or in <code>_targets.jl</code> to avoid this. It is a global setting, so Targets does not change it for you.</p><h2 id="Targets-that-must-not-run-concurrently" tabindex="-1">Targets that must not run concurrently <a class="header-anchor" href="#Targets-that-must-not-run-concurrently" aria-label="Permalink to &quot;Targets that must not run concurrently {#Targets-that-must-not-run-concurrently}&quot;">​</a></h2><p><code>deployment = :main</code> runs a target in the task that called <code>tar_make</code>, in your session, whatever the executor:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> figure </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> draw_with_gui_backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model)  deployment </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :main</span></span></code></pre></div><p>Two <code>:main</code> targets never run at the same time. While one runs, the build is busy running it, so no new jobs start, but jobs that were already running carry on. Use it for code that is not safe to run concurrently with itself. Code that is unsafe alongside <em>any</em> other use of a library needs every target that uses the library marked <code>:main</code>.</p><p><code>deployment = :main</code> does not choose a thread. Libraries that must run on Julia&#39;s first thread (such as PythonCall, or some GUI toolkits) are satisfied only when <code>tar_make</code> itself was called from that thread.</p><h2 id="Sharing-one-process" tabindex="-1">Sharing one process <a class="header-anchor" href="#Sharing-one-process" aria-label="Permalink to &quot;Sharing one process {#Sharing-one-process}&quot;">​</a></h2><p>With <code>jobs = n</code>, targets that run at the same time share your session: its memory, its global variables and its working directory. So target code must not:</p><ul><li><p><strong><code>cd</code></strong>: the project root is the working directory for the whole build; use paths relative to it instead.</p></li><li><p><strong>change <code>ENV</code></strong> or other global settings that other targets read.</p></li><li><p><strong>mutate its arguments.</strong> Every consumer of a target receives the same object, so a target that modifies its input in place races with the others, and corrupts the value for later consumers even with <code>jobs = 1</code>. Copy the input first.</p></li></ul><p><code>tar_make(check_mutation = true)</code> hashes every argument before and after each call, and errors, naming the target and argument, if a target changed one. It is slow, so it is off by default; turn it on in tests and CI.</p><p>More jobs also hold more values in memory at once. Values are released as soon as their last consumer in the build has finished, and <code>jobs</code> is the knob for peak memory.</p><h2 id="Worker-processes" tabindex="-1">Worker processes <a class="header-anchor" href="#Worker-processes" aria-label="Permalink to &quot;Worker processes {#Worker-processes}&quot;">​</a></h2><p>A <a href="/stable/api#Targets.DistributedExecutor"><code>DistributedExecutor</code></a> runs jobs on <code>Distributed</code> workers:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Distributed</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">addprocs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                                        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># four local workers</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tar_make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(executor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> DistributedExecutor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">workers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()))</span></span></code></pre></div><p>Workers are worth their start-up cost for long targets that allocate a lot, for libraries that are not safe to use from several tasks of one process, for code that might crash, and for using more than one machine. For many small targets, <code>jobs = n</code> is cheaper.</p><h3 id="What-happens" tabindex="-1">What happens <a class="header-anchor" href="#What-happens" aria-label="Permalink to &quot;What happens {#What-happens}&quot;">​</a></h3><ul><li><p><strong>Start-up.</strong> Each worker loads Targets and <code>_targets.jl</code> itself, so <code>_targets.jl</code> must load every package its targets need. Functions are never sent between processes: a worker looks targets up by name in its own copy of the pipeline. The build then checks that every worker can see the store, and that every worker computes the same code hashes as your session, and refuses to start otherwise.</p></li><li><p><strong>Workers keep what they loaded.</strong> A worker loads <code>_targets.jl</code> once and reuses it in later builds, and it keeps the packages it loaded. After editing <code>_targets.jl</code> or your functions, start new workers (<code>rmprocs(workers()); addprocs(4)</code>); otherwise the start-up check reports the targets whose code differs.</p></li><li><p><strong>Each job.</strong> Your session sends the job&#39;s arguments to a worker (a copy, so large inputs cost transfer time). The worker runs the target and writes the value to the store itself, and sends back only its hash and record. Your session alone writes the metadata; consumers that need the value load it from the store.</p></li><li><p><strong>The store must be on a filesystem that every worker shares</strong> with your session, such as a cluster&#39;s shared home or scratch directory.</p></li><li><p><code>deployment = :main</code> targets still run in your session.</p></li></ul><h3 id="Slots-on-workers" tabindex="-1">Slots on workers <a class="header-anchor" href="#Slots-on-workers" aria-label="Permalink to &quot;Slots on workers {#Slots-on-workers}&quot;">​</a></h3><p>The build has <code>slots_per_worker</code> slots per worker (default 1), and each job goes to the worker with the most free slots. A job always runs on a single worker, so it is given at most <code>slots_per_worker</code> slots there (that is what <code>tar_slots()</code> returns). A target with more <code>slots</code> than that still occupies them in the build, which keeps other jobs from starting: a <code>slots = :all</code> target waits for every worker to finish its jobs, then runs alone on one of them.</p><h3 id="Threads-on-workers" tabindex="-1">Threads on workers <a class="header-anchor" href="#Threads-on-workers" aria-label="Permalink to &quot;Threads on workers {#Threads-on-workers}&quot;">​</a></h3><p>Workers start with one thread unless you give them more. Distributed runs every job a worker receives as a task tied to one thread, so the jobs running on one worker take turns, however many threads it has. In practice:</p><ul><li><p><strong>For targets that are not parallel themselves</strong>, use one slot per worker (the default) and as many workers as you want targets running at once.</p></li><li><p><strong>For targets that are parallel themselves</strong>, give workers threads, and let those targets start their own tasks, which can use all of the worker&#39;s threads:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">addprocs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; exeflags </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;--threads=8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tar_make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(executor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> DistributedExecutor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">workers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()))</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># in a target: OhMyThreads.tmap(f, xs; ntasks = Threads.nthreads())</span></span></code></pre></div><p><code>tar_slots()</code> is <code>1</code> here, since each worker has one slot; size the target&#39;s own tasks by the worker&#39;s threads instead.</p></li><li><p><code>slots_per_worker &gt; 1</code> lets a worker overlap jobs that mostly wait (I/O, external programs), as more jobs than threads do in your session.</p></li></ul><p>Local workers start with OpenBLAS limited to one thread; pass <code>addprocs(n; enable_threaded_blas = true)</code> for BLAS-heavy targets.</p><h3 id="Environments-and-machines" tabindex="-1">Environments and machines <a class="header-anchor" href="#Environments-and-machines" aria-label="Permalink to &quot;Environments and machines {#Environments-and-machines}&quot;">​</a></h3><p>Workers started with <code>addprocs(n)</code> on this machine use your session&#39;s active project. Workers on other machines, or started by a cluster manager, must load the same project and package versions, e.g. with <code>exeflags = &quot;--project=/path/to/project&quot;</code>. If they load different code, the start-up check names the targets whose code differs. For Slurm clusters, see <a href="./slurm">Running on a Slurm cluster</a>.</p><h3 id="What-differs-from-jobs-n" tabindex="-1">What differs from <code>jobs = n</code> <a class="header-anchor" href="#What-differs-from-jobs-n" aria-label="Permalink to &quot;What differs from \`jobs = n\` {#What-differs-from-jobs-n}&quot;">​</a></h3><ul><li><p>Each job&#39;s arguments are a copy, so a target that mutates them cannot affect other targets; <code>check_mutation</code> does not check jobs that run on workers.</p></li><li><p>A crash (for example a segmentation fault in a C library) ends that worker rather than your session, and the target that was running on it fails.</p></li><li><p>Warnings from targets are printed as <code>From worker N: ...</code>.</p></li><li><p>Quarto renders on workers never print their output.</p></li><li><p><code>fresh = true</code> cannot be combined with <code>executor</code>: workers attach to the session that started them, not to the new process a fresh build runs in.</p></li></ul><h2 id="Summary" tabindex="-1">Summary <a class="header-anchor" href="#Summary" aria-label="Permalink to &quot;Summary {#Summary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;"></th><th style="text-align:right;"><code>jobs = n</code> (tasks)</th><th style="text-align:right;"><code>DistributedExecutor</code> (workers)</th></tr></thead><tbody><tr><td style="text-align:right;">Runs in</td><td style="text-align:right;">your session</td><td style="text-align:right;">separate processes</td></tr><tr><td style="text-align:right;">Start-up cost</td><td style="text-align:right;">none</td><td style="text-align:right;">starting workers and loading packages and <code>_targets.jl</code> in each</td></tr><tr><td style="text-align:right;">Cost per job</td><td style="text-align:right;">small</td><td style="text-align:right;">copying arguments to the worker; values go through the store</td></tr><tr><td style="text-align:right;">Memory</td><td style="text-align:right;">shared by every target</td><td style="text-align:right;">separate per worker</td></tr><tr><td style="text-align:right;">Code unsafe to run concurrently</td><td style="text-align:right;">needs <code>deployment = :main</code></td><td style="text-align:right;">isolated in its own process</td></tr><tr><td style="text-align:right;">A crash</td><td style="text-align:right;">ends the session</td><td style="text-align:right;">ends one worker</td></tr><tr><td style="text-align:right;">Machines</td><td style="text-align:right;">one</td><td style="text-align:right;">several, with a shared filesystem</td></tr><tr><td style="text-align:right;">CPU parallelism</td><td style="text-align:right;">up to the session&#39;s threads</td><td style="text-align:right;">one job per worker, plus each target&#39;s own tasks</td></tr></tbody></table>`,54)])])}const g=t(r,[["render",o]]);export{k as __pageData,g as default};
